import java.util.*;

public class Main {
    static final int INF = 10000000;
    static final int M = 21000;

    static int n, timeSteps;
    static int[][][] stone;
    static int[][][][][] dp;
    static int[][] sci, ca;
    static char[][] str, str2;
    static int[][] dir = {{-1,0},{1,0},{0,-1},{0,1}};

    static int[] head, next;
    static Edge[] edge;
    static int e;

    static class Edge {
        int v, w;
        Edge(int v, int w) {
            this.v = v;
            this.w = w;
        }
    }

    static void addEdge(int u, int v, int w) {
        edge[e] = new Edge(v, w);
        next[e] = head[u];
        head[u] = e++;
        edge[e] = new Edge(u, 0);
        next[e] = head[v];
        head[v] = e++;
    }

    static void expand() {
        for (int k = 1; k <= timeSteps; ++k) {
            for (int i = 1; i <= n; ++i) {
                for (int j = 1; j <= n; ++j) {
                    if (stone[k-1][i][j] == 1) {
                        stone[k][i][j] = 1;
                    } else if (stone[k-1][i][j] == 2) {
                        stone[k][i][j] = 2;
                    } else {
                        boolean found = false;
                        for (int z = 0; z < 4; ++z) {
                            int nx = i + dir[z][0];
                            int ny = j + dir[z][1];
                            if (nx >= 1 && nx <= n && ny >= 1 && ny <= n) {
                                if (stone[k-1][nx][ny] == 2) {
                                    stone[k][i][j] = 2;
                                    found = true;
                                    break;
                                }
                            }
                        }
                        if (!found) {
                            stone[k][i][j] = 0;
                        }
                    }
                }
            }
        }
    }

    static void dfs(int x, int y, int nowx, int nowy, int k, boolean[][] vis) {
        vis[nowx][nowy] = true;
        dp[k][x][y][nowx][nowy] = 1;
        if (k >= timeSteps || stone[k][nowx][nowy] != 0) return;
        for (int z = 0; z < 4; ++z) {
            int nx = nowx + dir[z][0];
            int ny = nowy + dir[z][1];
            if (nx >= 1 && nx <= n && ny >= 1 && ny <= n && !vis[nx][ny]) {
                if (stone[k][nx][ny] != 0) continue;
                dfs(x, y, nx, ny, k+1, vis);
            }
        }
    }

    static int SAP(int s, int t) {
        int maxNode = t + 1;
        int[] dist = new int[maxNode + 5];
        int[] gap = new int[maxNode + 5];
        int[] arc = new int[maxNode + 5];
        int[] pre = new int[maxNode + 5];
        boolean[] inq = new boolean[maxNode + 5];
        int[] q = new int[maxNode * 2];

        Arrays.fill(arc, -1);
        Arrays.fill(pre, -1);

        int qf = 0, qr = 0;
        q[qr++] = t;
        inq[t] = true;
        gap[0]++;
        dist[t] = 0;
        arc[t] = head[t];

        while (qf < qr) {
            int u = q[qf++];
            for (int i = head[u]; i != -1; i = next[i]) {
                int v = edge[i].v;
                if (!inq[v]) {
                    q[qr++] = v;
                    inq[v] = true;
                    dist[v] = dist[u] + 1;
                    gap[dist[v]]++;
                    arc[v] = head[v];
                }
            }
        }

        int low = INF;
        int u = s;
        int ans = 0;
        pre[s] = s;

        while (dist[s] < t) {
            boolean flag = false;
            int i = arc[u];
            while (i != -1) {
                if (edge[i].w > 0 && dist[edge[i].v] + 1 == dist[u]) {
                    flag = true;
                    low = Math.min(low, edge[i].w);
                    pre[edge[i].v] = u;
                    u = edge[i].v;
                    if (u == t) {
                        while (u != s) {
                            u = pre[u];
                            edge[arc[u]].w -= low;
                            edge[arc[u] ^ 1].w += low;
                        }
                        ans += low;
                        low = INF;
                    }
                    arc[u] = i;
                    break;
                }
                i = next[i];
            }
            if (flag) continue;

            int mindis = t + 1;
            int j = head[u];
            while (j != -1) {
                if (edge[j].w > 0 && mindis > dist[edge[j].v]) {
                    mindis = dist[edge[j].v];
                    arc[u] = j;
                }
                j = next[j];
            }
            gap[dist[u]]--;
            if (gap[dist[u]] == 0) return ans;
            dist[u] = mindis + 1;
            gap[dist[u]]++;
            u = pre[u];
        }
        return ans;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        timeSteps = sc.nextInt();
        sc.nextLine(); // consume newline

        str = new char[n+2][n+2];
        str2 = new char[n+2][n+2];
        sci = new int[n+2][n+2];
        ca = new int[n+2][n+2];
        stone = new int[timeSteps+1][n+2][n+2];
        dp = new int[timeSteps+1][n+2][n+2][n+2][n+2];

        for (int i = 1; i <= n; ++i) {
            String line = sc.next();
            for (int j = 1; j <= n; ++j) {
                str[i][j] = line.charAt(j-1);
                if (str[i][j] == 'Z') {
                    stone[0][i][j] = 2;
                } else if (str[i][j] == 'Y') {
                    stone[0][i][j] = 1;
                } else {
                    sci[i][j] = str[i][j] - '0';
                }
            }
        }

        for (int i = 1; i <= n; ++i) {
            String line = sc.next();
            for (int j = 1; j <= n; ++j) {
                str2[i][j] = line.charAt(j-1);
                if (str2[i][j] >= '0' && str2[i][j] <= '9') {
                    ca[i][j] = str2[i][j] - '0';
                }
            }
        }

        expand();

        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= n; ++j) {
                if (sci[i][j] > 0) {
                    boolean[][] vis = new boolean[n+2][n+2];
                    dfs(i, j, i, j, 0, vis);
                }
            }
        }

        for (int k = 1; k <= timeSteps; ++k) {
            for (int x = 1; x <= n; ++x) {
                for (int y = 1; y <= n; ++y) {
                    for (int nx = 1; nx <= n; ++nx) {
                        for (int ny = 1; ny <= n; ++ny) {
                            dp[k][x][y][nx][ny] += dp[k-1][x][y][nx][ny];
                        }
                    }
                }
            }
        }

        int S = 0;
        int T = n * n * 2 + 1;
        int maxNodes = T + 1;
        head = new int[maxNodes + 5];
        Arrays.fill(head, -1);
        next = new int[M];
        edge = new Edge[M];
        e = 0;

        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= n; ++j) {
                if (sci[i][j] > 0) {
                    addEdge(S, (i-1)*n + j, sci[i][j]);
                }
            }
        }

        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= n; ++j) {
                if (ca[i][j] > 0) {
                    addEdge(n*n + (i-1)*n + j, T, ca[i][j]);
                }
            }
        }

        for (int x = 1; x <= n; ++x) {
            for (int y = 1; y <= n; ++y) {
                for (int nx = 1; nx <= n; ++nx) {
                    for (int ny = 1; ny <= n; ++ny) {
                        if (sci[x][y] > 0 && ca[nx][ny] > 0) {
                            if (dp[timeSteps][x][y][nx][ny] > 0) {
                                addEdge((x-1)*n + y, n*n + (nx-1)*n + ny, INF);
                            }
                        }
                    }
                }
            }
        }

        int ans = SAP(S, T);
        System.out.println(ans);
        sc.close();
    }
}
